from __future__ import annotations
import requests
from config.settings import BASE_URL, TIMEOUT_SECONDS, TOKEN

class ApiClient:
    def __init__(self, base_url: str = BASE_URL) -> None:
        self.session = requests.Session()
        self.base_url = base_url.rstrip('/')
        if TOKEN:
            self.session.headers.update({'Authorization': f'Bearer {TOKEN}'})

    def get(self, path: str, **kwargs) -> requests.Response:
        return self.session.get(f'{self.base_url}{path}', timeout=TIMEOUT_SECONDS, **kwargs)

    def post(self, path: str, json: dict, **kwargs) -> requests.Response:
        return self.session.post(f'{self.base_url}{path}', json=json, timeout=TIMEOUT_SECONDS, **kwargs)

